// 语法 (grammar) data API — separate from the flashcard/texts modules.
// Grammar data lives in src/data/grammar/{series}-{unit}.json (generated by
// scripts/convert_grammar.py) and is lazy-loaded, one chunk per unit.
// The glob pattern requires a dash so grammar/meta.json is excluded.

import meta from "./grammar/meta.json"; // { "hsk-1": { lessonCount, pointCount }, ... }

const loaders = import.meta.glob("./grammar/*-*.json");

function key(seriesId, unitId) {
  return `${seriesId}-${unitId}`;
}

export function hasGrammar(seriesId, unitId) {
  return !!meta[key(seriesId, unitId)];
}

const _cache = new Map();
export function loadGrammarUnit(seriesId, unitId) {
  const k = key(seriesId, unitId);
  if (_cache.has(k)) return _cache.get(k);
  const loader = loaders[`./grammar/${k}.json`];
  const p = loader ? loader().then((m) => m.default) : Promise.resolve(null);
  _cache.set(k, p);
  return p;
}

export const getGrammarUnit = loadGrammarUnit;

export async function getGrammarLesson(seriesId, unitId, lessonNum) {
  const ds = await loadGrammarUnit(seriesId, unitId);
  if (!ds) return null;
  return ds.lessons.find((l) => l.num === Number(lessonNum)) || null;
}
